"""Original COPD chapter: exacerbations, respiratory support and advanced care."""
from create_copd import rows,q,GO,ME
from qbank_authoring import ref,finalize
NV=ref('ATS: Long-Term NIV in Chronic Stable Hypercapnic COPD, 2020','https://pmc.ncbi.nlm.nih.gov/articles/PMC7427384/')
LO=ref('LOTT: Long-Term Oxygen in COPD With Moderate Desaturation','https://www.nejm.org/doi/full/10.1056/NEJMoa1604344')
q('A COPD exacerbation produces increased wheeze and breathlessness. Which bronchodilator strategy is standard initial care?', 'Short-acting inhaled beta-2 agonist with or without a short-acting antimuscarinic',[
 ('A biologic injection as the only immediate rescue','Biologics are selected maintenance therapies.'),('Roflumilast as the fastest bronchodilator','It is not an acute rescue bronchodilator.'),('Routine IV aminophylline before inhaled treatment','Methylxanthines are not routinely recommended because of limited benefit and toxicity.')],
 'Acute symptom relief uses a rapidly acting inhaled treatment', '**Delivery depends on severity and the patient’s ability.**',['A spacer or nebulized route can be used as appropriate.','Monitor response and adverse effects.'], '**Assess whether the episode is truly a COPD exacerbation.**',['Pneumonia, pulmonary embolism, pneumothorax and heart failure can mimic or coexist.','Treat oxygen and ventilatory problems in parallel.'],[['Initial bronchodilator','SABA with or without SAMA'],['Maintenance add-ons','Not immediate substitutes'],['Assessment','Look for competing acute causes']],[GO],'clinical_scenario')
q('What systemic corticosteroid course is commonly recommended for a significant adult COPD exacerbation?', 'Prednisone-equivalent 40 mg daily for five days, unless the individual situation requires another plan',[
 ('High-dose treatment for several months in every event','This adds substantial harm without routine benefit.'),('No systemic steroid can ever help an exacerbation','Short courses can improve recovery in appropriate cases.'),('The exact same course is obligatory despite every contraindication or alternate diagnosis','Clinical context still matters.')],
 'Use the shortest effective evidence-based acute course', '**A short course reduces unnecessary cumulative exposure.**',['Oral treatment is usually suitable when absorption is reliable.','Hyperglycemia, infection and psychiatric effects require attention.'], '**Do not convert an acute course into unreviewed chronic therapy.**',['Review recurrent events and maintenance prevention.','Use a different approach when the episode has another primary cause.'],[['Common regimen','40 mg prednisone-equivalent'],['Duration','Five days'],['Safety','Limit cumulative steroid harm']],[GO])
q('Which exacerbation feature most strongly supports antibiotics in COPD?', 'Increased sputum purulence with a compatible clinical exacerbation, especially with other cardinal symptoms or ventilatory support needs',[
 ('Every increase in breathlessness without any infection assessment','Nonbacterial and alternative causes are common.'),('Stable chronic cough alone with no change','This does not establish an acute bacterial indication.'),('A high eosinophil count as proof of bacteria','Eosinophilia is not a bacterial test.')],
 'Select antibiotics for likely bacterial or severe supported contexts', '**Purulence, sputum amount and dyspnea are assessed together.**',['Need for invasive or noninvasive ventilation can support treatment.','Local resistance, prior cultures and severity determine the agent.'], '**Use an appropriate short course and reassess.**',['Do not miss pneumonia or bronchiectasis-related microbiology.','Avoid unnecessary broad coverage from the COPD label alone.'],[['Clinical clue','New purulence'],['Other factors','Cardinal symptoms/severity/support'],['Selection','Local and patient microbiology']],[GO])
q('A hypoxemic COPD exacerbation is being treated with oxygen while blood gases are assessed. What is the usual initial saturation target?', '88–92%',[
 ('100% for every patient regardless of CO2','Uncontrolled hyperoxia can worsen hypercapnia.'),('Below 80% to preserve breathing drive','Dangerous hypoxemia must not be accepted.'),('A fixed flow without checking saturation','Treatment should be titrated.')],
 'Correct hypoxemia without unnecessary oxygen excess', '**Controlled oxygen reduces the risk of oxygen-induced hypercapnia.**',['Blood gases assess pH and PaCO2.','The target can be individualized after the complete assessment.'], '**Do not withhold oxygen from a severely hypoxemic patient.**',['Titrate and monitor rather than choosing between no oxygen and unlimited oxygen.','Assess the need for ventilatory support.'],[['Usual acute target','88–92%'],['Blood gas','Ventilation and acid-base status'],['Method','Controlled titration']],[GO],'clinical_scenario')
q('COPD exacerbation causes pH 7.28 and PaCO2 68 mmHg despite initial treatment. The patient is cooperative and can protect the airway. What support is usually appropriate?', 'A monitored trial of noninvasive ventilation',[
 ('Oxygen alone is sufficient regardless of acidosis','Ventilatory failure requires more than oxygen delivery.'),('NIV is contraindicated by every elevated PaCO2','Hypercapnic acidosis is a major indication.'),('Sedation alone to suppress tachypnea','This can worsen ventilation.')],
 'Bilevel support can reduce work of breathing and improve ventilation', '**NIV improves important outcomes in suitable acute hypercapnic COPD.**',['Monitor pH, respiratory effort, consciousness and tolerance.','A plan for failure and intubation must be clear.'], '**Do not delay escalation if the trial fails.**',['Treat the exacerbation and its trigger concurrently.','Reassess promptly rather than waiting many hours on ineffective support.'],[['Indication','Acute hypercapnic acidosis'],['Candidate','Airway protection and cooperation'],['Safety','Close monitoring and failure plan']],[GO],'clinical_scenario')
q('A COPD patient on NIV becomes increasingly obtunded with worsening acidosis and cannot protect the airway. What is the best next principle?', 'Urgent assessment for invasive ventilation rather than prolonging a failing NIV trial',[
 ('Increase mask time indefinitely without reassessment','This can dangerously delay definitive support.'),('A mask guarantees protection from aspiration','It does not secure the airway.'),('Ignore consciousness if the oxygen saturation is acceptable','Ventilation and airway protection remain critical.')],
 'Noninvasive treatment has a defined failure boundary', '**Worsening mental status, instability and persistent gas deterioration are warning signs.**',['Goals of care and the patient’s wishes affect the support ceiling.','If invasive care is appropriate, delay can worsen outcome.'], '**Escalate with an experienced team.**',['Continue resuscitation and cause treatment.','Document a clear support plan from the start of NIV.'],[['Failure clues','Consciousness/acidosis worsens'],['Airway','May need protection'],['Action','Timely invasive-support decision']],[GO],'clinical_scenario')
q('What mechanism contributes importantly to oxygen-induced hypercapnia in susceptible COPD patients?', 'Worsened ventilation-perfusion matching from reversal of hypoxic vasoconstriction, with other effects including the Haldane effect',[
 ('Complete loss of every respiratory drive is the sole explanation','The traditional single-mechanism explanation is incomplete.'),('Oxygen directly creates bicarbonate without any gas-exchange change','This is not the key mechanism.'),('The risk means hypoxemia should remain untreated','Controlled oxygen is needed.')],
 'The physiology is broader than a “hypoxic drive” slogan', '**More blood can reach poorly ventilated lung units when hypoxic vasoconstriction is reversed.**',['Oxygenation of hemoglobin also affects CO2 carriage.','Some change in ventilation can contribute.'], '**Use controlled oxygen and blood-gas monitoring.**',['Treat severe hypoxemia promptly.','Do not reflexively remove oxygen without a monitored correction plan.'],[['V/Q','Can worsen with excess oxygen'],['Haldane effect','Changes CO2 carriage'],['Care','Titration rather than avoidance']],[GO])
q('A clinically stable COPD patient has persistent PaO2 52 mmHg on room air despite optimized treatment. Which intervention has an established survival role?', 'Long-term oxygen therapy when confirmed and prescribed appropriately',[
 ('Oxygen only for a few minutes during each clinic visit','That does not reproduce the long-term treatment evidence.'),('No oxygen because all COPD oxygen causes harm','Severe chronic hypoxemia is a different indication from uncontrolled acute hyperoxia.'),('An antibiotic regardless of infection','It does not correct the chronic oxygen deficit.')],
 'Severe stable resting hypoxemia has a specific treatment evidence base', '**GOLD includes PaO2 at most 55 mmHg or comparably severe saturation criteria.**',['Persistent values should be established in a stable state.','A threshold above 55 but below 60 can qualify with specified complications.'], '**Prescribe duration and delivery with reassessment.**',['Smoking and fire safety are essential.','Oxygen initiated during an exacerbation may not remain necessary after recovery.'],[['PaO2','52 mmHg in this case'],['State','Stable and persistent'],['Role','LTOT survival benefit in eligible severe hypoxemia']],[GO],'clinical_scenario')
q('What did LOTT show for stable COPD with moderate resting or exercise desaturation?', 'Routine long-term oxygen did not prolong time to death or first hospitalization in the studied group',[
 ('The severe-resting-hypoxemia survival benefit applies identically to all mild desaturation','The populations differ.'),('All symptomatic oxygen use is automatically prohibited','Selected symptom and activity decisions require individual assessment.'),('The trial means oxygen is harmful in every COPD patient','That is not its conclusion.')],
 'Do not extrapolate severe-hypoxemia evidence to every low-normal saturation', '**LOTT included moderate resting saturation around 89–93% and selected exercise desaturation.**',['The outcome did not support routine LTOT for this whole group.','Severe chronic hypoxemia remains a separate indication.'], '**Use the actual indication and patient-centered goals.**',['Assess exertional needs using appropriate testing.','Avoid prescribing lifelong equipment from one borderline reading.'],[['Studied state','Moderate desaturation'],['Main result','No death/first-hospitalization benefit'],['Contrast in indication','Severe resting hypoxemia differs']],[LO,GO])
q('Hypercapnia persists after recovery from an acute COPD episode requiring NIV. What approach is supported by ATS guidance for long-term home NIV?', 'Reassess persistent hypercapnia after about two to four weeks and consider nocturnal NIV in an appropriate stable patient',[
 ('Every transient admission CO2 elevation mandates lifelong NIV immediately','Some hypercapnia resolves with recovery.'),('Screening for coexisting OSA is irrelevant','ATS recommends considering overlap assessment before long-term NIV.'),('No stable hypercapnic COPD patient can benefit','Selected patients can benefit.')],
 'Acute support and chronic support require separate decisions', '**The guideline favors reassessment after resolution rather than routine in-admission long-term initiation.**',['Persistent severity and clinical phenotype determine suitability.','A patient unable to wean from support may require a different immediate pathway.'], '**Set ventilatory targets and follow-up explicitly.**',['Review OSA, adherence and interface tolerance.','Do not provide equipment without monitoring its physiological effect.'],[['Timing','About two to four weeks after recovery'],['Candidate','Persistent stable hypercapnia'],['Assessment','OSA and practical suitability']],[NV],'clinical_scenario')
q('A patient with advanced COPD has progressive weight and muscle loss. What is an appropriate management principle?', 'Assess nutritional causes and combine individualized nutrition with rehabilitation and resistance activity when feasible',[
 ('Low BMI is always beneficial and needs no review','Cachexia and low muscle mass can worsen prognosis and function.'),('Only inhaler dose determines body composition','Systemic, dietary and activity factors matter.'),('A calorie prescription alone replaces the need to exclude cancer or other disease','The cause must be assessed.')],
 'COPD burden includes skeletal muscle and nutritional effects', '**Breathlessness can limit eating and activity.**',['Inflammation and other diseases can contribute to wasting.','Functional assessment can reveal sarcopenia beyond body weight.'], '**Treat reversible causes and support strength.**',['Adapt food and exercise to respiratory limitations.','Use multidisciplinary care rather than accepting unexplained loss as inevitable.'],[['Problem','Cachexia/sarcopenia'],['Evaluation','Intake, activity and alternate disease'],['Care','Nutrition plus rehabilitation']],[GO],'clinical_scenario')
q('Breathlessness suddenly worsens in a COPD patient with new leg edema and orthopnea. What is the best diagnostic principle?', 'Assess heart failure and other competing causes rather than assuming every deterioration is airway exacerbation',[
 ('A COPD diagnosis excludes cardiac disease','The diseases commonly coexist.'),('No imaging or cardiac assessment is useful in COPD','Selected testing can identify a treatable alternate cause.'),('Increase systemic steroids indefinitely without reassessment','This can worsen some comorbid problems.')],
 'Comorbidity can mimic or amplify an exacerbation', '**Heart failure, pulmonary embolism and pneumonia are important alternatives.**',['Clinical chronology and objective tests refine the probability.','Airway and cardiac processes can occur together.'], '**Treat each established mechanism.**',['Review fluid status and medication effects.','Do not let a familiar diagnostic label close the assessment prematurely.'],[['New pattern','Orthopnea/edema'],['Concern','Cardiac contribution'],['Approach','Integrated differential and treatment']],[GO],'clinical_scenario')
q('Which statement about alpha-1 antitrypsin augmentation is most accurate?', 'It is a specialist option for selected severe deficiency with emphysema, not routine therapy for all COPD or every carrier state',[
 ('Every PiMZ carrier automatically needs augmentation','The indication is not universal.'),('It substitutes for smoking cessation','Exposure avoidance remains essential.'),('It is an immediate bronchodilator for an acute attack','It is a different long-term treatment strategy.')],
 'A confirmed molecular phenotype is necessary for targeted therapy', '**Severity of deficiency, lung disease and local authorization guide eligibility.**',['Evidence endpoints and clinical benefit need a balanced discussion.','Liver disease requires its own assessment.'], '**Use genetic counseling and family testing appropriately.**',['Continue standard COPD care.','Do not infer the regimen from a low single level during an uncertain illness context.'],[['Eligibility','Selected severe deficiency'],['Role','Long-term specialist treatment'],['Still needed','Exposure avoidance and COPD management']],[GO])
q('Severe emphysema with hyperinflation remains disabling despite optimized care. What determines suitability for lung-volume-reduction intervention?', 'Detailed emphysema distribution, physiology, collateral ventilation, comorbidity and multidisciplinary selection',[
 ('Every low FEV1 makes any procedure beneficial','Some physiological patterns confer high risk or little benefit.'),('A single chest radiograph is enough for all decisions','CT and detailed assessment are needed.'),('Bronchoscopic valves are equally effective with any collateral ventilation pattern','Collateral ventilation affects valve response.')],
 'Mechanical reduction can help a selected phenotype', '**Surgical and bronchoscopic approaches have different eligibility and risks.**',['Hyperinflation and target-lobe anatomy matter.','Pulmonary rehabilitation and smoking status are part of the pathway.'], '**Use an experienced emphysema team.**',['Do not promise benefit from severity alone.','Consider transplantation in appropriate advanced disease.'],[['Assessment','CT and physiology'],['Valve factor','Collateral ventilation'],['Decision','Expert multidisciplinary selection']],[GO],'clinical_scenario')
q('When should supportive and palliative care be considered in advanced COPD?', 'Alongside active disease treatment when symptom burden, function or planning needs warrant it',[
 ('Only in the final hours after all active care stops','Earlier integrated support can help.'),('It requires stopping every inhaler and rehabilitation','The approaches can coexist.'),('A prognostic score removes the need to discuss individual goals','Preferences and clinical context remain essential.')],
 'Supportive care addresses the lived burden of disease', '**Breathlessness, anxiety, fatigue and caregiver needs deserve attention.**',['Advance care planning can clarify preferences before a crisis.','Treatment of refractory symptoms requires evidence-based individualized selection.'], '**Discuss support ceilings and emergency plans sensitively.**',['Do not equate planning with abandonment.','Revisit decisions as health and wishes change.'],[['Timing','According to need'],['Scope','Symptoms and planning'],['Relationship','Integrated with active care']],[GO])
q('After hospitalization for a COPD exacerbation, what is a key discharge strategy?', 'Review maintenance treatment and technique, arrange early follow-up and rehabilitation, and reassess oxygen or support needs after recovery',[
 ('Continue every acute treatment indefinitely without review','Steroids, antibiotics and oxygen may have time-limited indications.'),('No follow-up is needed if wheeze improves','Readmission and residual risk remain important.'),('A new inhaler without education is sufficient','Delivery and understanding affect the outcome.')],
 'The recovery phase is a high-risk transition', '**Reconcile medicines and confirm a practical action plan.**',['Address smoking, vaccination and comorbidity.','Rehabilitation after an event can improve recovery.'], '**Schedule reassessment rather than leaving temporary support unreviewed.**',['Oxygen need can change.','Persistent hypercapnia requires a defined long-term support evaluation.'],[['Before discharge','Regimen, skills and plan'],['Early follow-up','Response and barriers'],['Later reassessment','Oxygen/NIV and recovery needs']],[GO,NV])

